sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;
    if (!newValue) {
        g_form.setDisplay('assigned_to_user', true);
        g_form.setDisplay('assigned_to_device', true);
        return;
    }
    var ga = new GlideAjax('x_1970512_softwa_0.SAMLUtils');
    ga.addParam('sysparm_name', 'getLicensingMetric');
    ga.addParam('sysparm_entitlement_id', newValue);
    ga.getXMLAnswer(function(answer) {
        if (answer === 'per_user' || answer === 'per_concurrent_user') {
            g_form.setDisplay('assigned_to_user', true);
            g_form.setDisplay('assigned_to_device', false);
            g_form.setValue('assigned_to_device', '');
        } else if (answer === 'per_device' || answer === 'per_core') {
            g_form.setDisplay('assigned_to_user', false);
            g_form.setDisplay('assigned_to_device', true);
            g_form.setValue('assigned_to_user', '');
        } else {
            g_form.setDisplay('assigned_to_user', true);
            g_form.setDisplay('assigned_to_device', true);
        }
    });
}
